import React from 'react';

export default function EventDetails({ event, onClose }) {
  if (!event) return null;

  return (
    <div className="panel event-details">
      <button
        onClick={onClose}
        style={{
          float: 'right',
          background: 'transparent',
          border: 'none',
          fontSize: 18,
          cursor: 'pointer'
        }}
      >
        ×
      </button>

      <h3>{event.title}</h3>

      <img
        src={event.image_url || 'https://via.placeholder.com/800x300'}
        alt={event.title}
        style={{
          width: '100%',
          height: 240,
          objectFit: 'cover',
          borderRadius: 8
        }}
      />

      <p style={{ marginTop: 12 }}>{event.description}</p>

      <div style={{ marginTop: 12 }}>
        <button className="buttons primary">Volunteer for this</button>
        <button className="buttons" style={{ marginLeft: 8 }}>Share</button>
      </div>
    </div>
  );
}
